import json
from http.server import BaseHTTPRequestHandler, HTTPServer
from database import query

def dispatch(method, path, body=b"", query_fn=None):
    query_fn = query_fn or query
    try:
        if method == "GET" and path == "/health":
            query_fn("SELECT id FROM public.notes LIMIT 0")
            return 200, {"status": "ok"}
        if method == "GET" and path == "/notes":
            rows = query_fn("SELECT id, body FROM public.notes ORDER BY id")
            return 200, {"notes": [{"id": row[0], "body": row[1]} for row in rows]}
        if method == "POST" and path == "/notes":
            try:
                payload = json.loads(body)
            except (ValueError, UnicodeDecodeError):
                return 400, {"error": "invalid JSON"}
            text = payload.get("body") if isinstance(payload, dict) else None
            if not isinstance(text, str) or not 1 <= len(text.strip()) <= 280:
                return 400, {"error": "body must contain 1 to 280 characters"}
            row = query_fn("INSERT INTO public.notes (body) VALUES (%s) RETURNING id", (text.strip(),))[0]
            return 201, {"id": row[0], "body": text.strip()}
        return 404, {"error": "not found"}
    except Exception:
        return 503, {"error": "database unavailable"}

class Handler(BaseHTTPRequestHandler):
    def respond(self):
        try:
            size = int(self.headers.get("Content-Length", "0"))
            if not 0 <= size <= 8192:
                raise ValueError("invalid body length")
            status, payload = dispatch(self.command, self.path, self.rfile.read(size))
        except ValueError:
            status, payload = 400, {"error": "invalid body length"}
        data = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    do_GET = respond
    do_POST = respond

if __name__ == "__main__":
    HTTPServer(("0.0.0.0", 8080), Handler).serve_forever()
